import{z as A,x as s,o as t,c as B,q as i,j as m,D as e,d as o,s as n,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Merton 组合：实现与校准","description":"","frontmatter":{"title":"Merton 组合：实现与校准","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/merton-portfolio-implementation.md","filePath":"quant/merton-portfolio-implementation.md","lastUpdated":1791063341000}'),p={name:"quant/merton-portfolio-implementation.md"};function u(d,a,g,C,f,h){const r=s("Mermaid");return t(),B("div",null,[a[2]||(a[2]=i('<h1 id="merton-组合-实现与校准" tabindex="-1">Merton 组合：实现与校准 <a class="header-anchor" href="#merton-组合-实现与校准" aria-label="Permalink to &quot;Merton 组合：实现与校准&quot;">​</a></h1><div class="epigraph"><p>连续时间对数或幂效用下，风险资产权重是超额收益对 $\\sigma^2$ 的比；把这个比当成已知常数去下单，校准误差会比公式本身更大。</p><footer>—— Merton, Lifetime Portfolio Selection under Uncertainty: the Continuous-Time Case, Review of Economics and Statistics, 1969</footer></div><p><a href="/quant/vol-targeting">上一课</a>把缩放日的母单执行收在参与率与同向抛压上。本课打开组合进阶：主干 <a href="/quant/markowitz">Markowitz</a> 是单期二次，<a href="/quant/kelly-sizing">Kelly</a> 已写出连续极限 \\(f\\approx\\mu/\\sigma^2\\) 与分数化。缺口是 <strong>Merton 公式的实现</strong>：估计 \\(\\mu,\\sigma\\)、对冲需求（对随机机会集）、以及为什么机构几乎从不下满公式仓。后课动态规划把离散再平衡写进同一问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Merton（1969/1971）在连续时间、完备市场、幂效用下给出：无随机利率与无随机 \\(\\mu\\) 时，风险资产权重 \\(\\pi=\\frac{1}{\\gamma}\\Sigma^{-1}(\\mu-r\\mathbf{1})\\)。对数效用 \\(\\gamma=1\\) 即 Kelly。问题不是再推 HJB，而是：<strong>\\(\\mu\\) 的估计误差被 \\(\\Sigma^{-1}\\) 放大</strong>，与 <a href="/quant/cov-shrinkage">协方差收缩</a> 同一病。公式当 \\(\\mu,\\Sigma\\) 已知；实现必须把估计、约束、交易费用放进去，否则权重会像样本前沿一样炸。</p><p>第二层：机会集若随机（随机 \\(\\mu\\) 或随机 \\(r\\)），最优仓还含对冲需求，对冲用的是状态变量上的衍生暴露。忽略对冲需求、只下 myopic \\(\\frac{1}{\\gamma}\\Sigma^{-1}(\\mu-r)\\)，在持久的预期收益因子上会系统性偏。</p><p><span class="marginnote">数字实例：\\(\\pi=\\mu/\\sigma^2\\) 对 \\(\\mu\\) 的敏感度是 \\(1/\\sigma^2\\)。取 \\(\\sigma=20\\%\\)，则 \\(1/\\sigma^2=25\\)——预期收益估错 1 个百分点，最优权重就整段偏 25 个百分点。而用 10 年月度数据估年化 \\(\\mu\\)，即使真实夏普有 0.5，估计标准误仍在 \\(\\pm 4\\%\\) 量级。这就是「\\(\\mu\\) 噪声被 \\(\\Sigma^{-1}\\) 放大」的具体尺寸。</span></p><h3 id="校准的是增长-不是下一季的均值" tabindex="-1">校准的是增长，不是下一季的均值 <a class="header-anchor" href="#校准的是增长-不是下一季的均值" aria-label="Permalink to &quot;校准的是增长，不是下一季的均值&quot;">​</a></h3><p>\\(\\mu\\) 用历史均值，噪声极大，Stambaugh 与 Merton 自己都强调预期收益难估。实务用：收缩 \\(\\mu\\) 向均衡（<a href="/quant/black-litterman">Black–Litterman</a>）、用更慢的状态变量、或直接放弃绝对 \\(\\mu\\)、改风险预算。\\(\\sigma\\) 相对好估，但仍有体制。把回测夏普代入 \\(\\pi=\\mathrm{SR}/(\\gamma\\sigma)\\)，与 Kelly 课的警告相同。</p><p><span class="marginnote">本课是金融组合实现，不是权重量化、也不是神经网络的权重量化。Merton 的 \\(\\pi\\) 是资金权重。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计：\\(\\Sigma\\) 用收缩或因子协方差；\\(\\mu\\) 用 BL 或宏观先验，禁止用短窗口股票均值。效用：\\(\\gamma\\) 从机构风险预算反推，不要从「我们是对数效用」宣布。约束：杠杆、卖空、行业，把闭式 \\(\\pi\\) 投影到可行集，见 <a href="/quant/portfolio-constraints">组合约束</a>。随机机会集：列出状态（收益率水平、估值、vol），用后课 DP 或对冲项的线性近似。对冲工具：债券、vol 衍生品，而不是把对冲需求再折进股票 \\(\\mu\\)。</p>',12)),(t(),m(l,null,{default:e(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%EF%BC%9A%E5%8E%86%E5%8F%B2%E6%94%B6%E7%9B%8A%E3%80%81%E5%AE%8F%E8%A7%82%E5%85%88%E9%AA%8C%E3%80%81%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%22%5D%20--%3E%20B%5B%22%CE%A3%20%E4%BC%B0%E8%AE%A1%EF%BC%9A%E6%94%B6%E7%BC%A9%E6%88%96%E5%9B%A0%E5%AD%90%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20A%20--%3E%20C%5B%22%CE%BC%20%E4%BC%B0%E8%AE%A1%EF%BC%9ABL%20%E6%88%96%E5%90%91%E5%9D%87%E8%A1%A1%E6%94%B6%E7%BC%A9%22%5D%0A%20%20B%20--%3E%20D%5B%22%E9%97%AD%E5%BC%8F%E8%A7%A3%20%CF%80%20%E7%AD%89%E4%BA%8E%201%2F%CE%B3%20%E4%B9%98%20%CE%A3%E9%80%86%20%E4%B9%98%E8%B6%85%E9%A2%9D%E6%94%B6%E7%9B%8A%22%5D%0A%20%20C%20--%3E%20D%0A%20%20D%20--%3E%20E%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%E5%8F%AF%E8%A1%8C%E9%9B%86%EF%BC%9A%E6%9D%A0%E6%9D%86%E3%80%81%E5%8D%96%E7%A9%BA%E3%80%81%E8%A1%8C%E4%B8%9A%E4%B8%8A%E9%99%90%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%88%86%E6%89%B9%E5%B0%8F%E6%9D%83%E9%87%8D%E4%B8%8A%E7%BA%BF%E5%B9%B6%E5%9B%9E%E6%B5%8B%E6%A0%A1%E9%AA%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"幂效用下 myopic 需求与对冲需求可加。Myopic 项吃的是瞬时夏普；对冲项吃的是状态对财富边际效用的相关。实现上前者被 \\(\\mu\\) 噪声淹没，后者被错误的状态变量淹没。所以「先把 myopic 做成可交易的风险平价，再小权重量对冲」往往比「全公式一次估齐」稳——这是工程分层，不是否定 Merton。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：myopic 需求就是「只看今天」的仓位——假装机会集永远不变，按当前夏普直接下 \\(\\mu/\\sigma^2\\)；对冲需求则是额外的仓位，用来对「未来投资机会变差」买保险。直觉类比：利率高时多拿债券，不只是因为今天划算，还因为利率将来回落时你的再投资收益会变差，现在多拿一点正好补上。")],-1)),(t(),m(l,null,{default:e(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Formula%5B%22%CF%80%20%E7%AD%89%E4%BA%8E%201%2F%CE%B3%20%CE%A3%20%E9%80%86%E4%B9%98%E8%B6%85%E9%A2%9D%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20Est%5B%22%CE%BC%20%E5%99%AA%E5%A3%B0%E8%A2%AB%20%CE%A3%20%E9%80%86%E6%94%BE%E5%A4%A7%22%5D%0A%20%20Formula%20--%3E%20Hedge%5B%22%E9%9A%8F%E6%9C%BA%E6%9C%BA%E4%BC%9A%E9%9B%86%E7%9A%84%E5%AF%B9%E5%86%B2%E9%9C%80%E6%B1%82%22%5D%0A%20%20Est%20--%3E%20Prac%5B%22%E6%94%B6%E7%BC%A9%20%CE%BC%20%E4%B8%8E%E5%8F%AF%E8%A1%8C%E9%9B%86%E6%8A%95%E5%BD%B1%22%5D%0A%20%20Hedge%20--%3E%20DP%5B%22%E5%90%8E%E8%AF%BE%E5%8A%A8%E6%80%81%E8%A7%84%E5%88%92%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不完备市场、交易费用、不可交易劳动收入，闭式消失。破产约束与杠杆上限使分数 Kelly 成为默认。连续再平衡假设与后课费用、税冲突。不要用 Merton 公式去给杠杆 ETF 的路径当「最优」，杠杆拖累在再后面一课。</p><p><span class="marginnote">常见误区：初学者容易以为「对数效用 \\(\\gamma=1\\)」是稳妥的中性默认，实际上它等价于全 Kelly，波动可以吃掉半个账户。机构的做法是反过来：先定「最大可忍受回撤」这类风险预算，再反推出 \\(\\gamma\\)——比如预算允许 20% 回撤、组合 vol 15%，倒推出的 \\(\\gamma\\) 大约在 2 到 3 之间，仓位随之砍半以上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Merton 权重在 \\(\\mu,\\Sigma\\) 已知时优雅；实现的主风险是 \\(\\mu\\) 估计与可行集。</li><li>随机机会集带来对冲需求，不能只用 myopic 项。</li><li>\\(\\gamma\\) 从风险预算反推；\\(\\mu\\) 要收缩或改用 BL。</li><li>出处：Merton, <em>REStat</em>, 1969；<em>JET</em>, 1971。</li></ul>',5))])}const F=A(p,[["render",u]]);export{D as __pageData,F as default};
